func makeVideoFrameInputWithSize(tb testing.TB, w, h int) (packetorframe.InputUnion, func()) {
	tb.Helper()
	cp := astiav.AllocCodecParameters()
	cp.SetMediaType(astiav.MediaTypeVideo)
	cp.SetWidth(w)
	cp.SetHeight(h)
	cp.SetPixelFormat(astiav.PixelFormatYuv420P)
	f := astiav.AllocFrame()
	f.SetWidth(w)
	f.SetHeight(h)
	f.SetPixelFormat(astiav.PixelFormatYuv420P)
	require.NoError(tb, f.AllocBuffer(32))
	streamInfo := &packetorframetypes.StreamInfo{
		CodecParameters: cp,
		StreamIndex:     0,
		StreamsCount:    1,
		TimeBase:        astiav.NewRational(1, 30),
	}
	frameInput := frame.BuildInput(f, 0, streamInfo)
	cleanup := func() {
		cp.Free()
		f.Free()
	}
	return packetorframe.InputUnion{Frame: &frameInput}, cleanup
}

