// makeCheckerboardYCbCr creates a YUV420 image with a checkerboard noise pattern
// in the Y plane. Bilateral filtering should measurably smooth this pattern.
func makeCheckerboardYCbCr(w, h int) *image.YCbCr {
	img := image.NewYCbCr(image.Rect(0, 0, w, h), image.YCbCrSubsampleRatio420)
	for y := range h {
		for x := range w {
			switch (x + y) % 2 {
			case 0:
				img.Y[y*img.YStride+x] = 200
			default:
				img.Y[y*img.YStride+x] = 40
			}
		}
	}
	// Fill chroma planes with neutral gray (128).
	for i := range img.Cb {
		img.Cb[i] = 128
		img.Cr[i] = 128
	}
	return img
}

// makeNoisyVideoFrameInput creates a frame with a checkerboard noise pattern
// so that bilateral filtering produces a measurable difference.
func makeNoisyVideoFrameInput(tb testing.TB, w, h int) (packetorframe.InputUnion, func()) {
	tb.Helper()
	input, cleanup := makeVideoFrameInputWithSize(tb, w, h)
	f := input.Frame.Frame

	img := makeCheckerboardYCbCr(w, h)
	require.NoError(tb, f.Data().FromImage(img))

	return input, cleanup
}

// frameToYCbCr extracts the Y/Cb/Cr planes from a frame as a Go image.
func frameToYCbCr(tb testing.TB, f *astiav.Frame) *image.YCbCr {
	tb.Helper()
	img := &image.YCbCr{}
	require.NoError(tb, f.Data().ToImage(img))
	return img
}

// computeYPlaneRMSE computes the root mean squared error between the Y planes
// of two YCbCr images. Returns math.MaxFloat64 if dimensions differ.
func computeYPlaneRMSE(a, b *image.YCbCr) float64 {
	if a.Rect.Dx() != b.Rect.Dx() || a.Rect.Dy() != b.Rect.Dy() {
		return math.MaxFloat64
	}
	w := a.Rect.Dx()
	h := a.Rect.Dy()

	var totalDiff int64
	for y := range h {
		for x := range w {
			va := int64(a.Y[y*a.YStride+x])
			vb := int64(b.Y[y*b.YStride+x])
			diff := va - vb
			totalDiff += diff * diff
		}
	}
	return math.Sqrt(float64(totalDiff) / float64(w*h))
}

// snapshotYPlane returns a copy of the Y plane data from a frame.
func snapshotYPlane(tb testing.TB, f *astiav.Frame) []byte {
	tb.Helper()
	img := frameToYCbCr(tb, f)
	cp := make([]byte, len(img.Y))
	copy(cp, img.Y)
	return cp
}

