// TestDeblemish_SendInput_WholeFrame_PixelsModified verifies that bilateral
// filtering actually changes pixel values when given a noisy input frame.
func TestDeblemish_SendInput_WholeFrame_PixelsModified(t *testing.T) {
	d, err := New(Config{Backend: BackendCPU})
	require.NoError(t, err)
	defer func() { _ = d.Close(context.Background()) }()

	input, cleanup := makeNoisyVideoFrameInput(t, 320, 240)
	defer cleanup()

	inputSnapshot := snapshotYPlane(t, input.Frame.Frame)

	outputCh := make(chan packetorframe.OutputUnion, 10)
	require.NoError(t, d.SendInput(context.Background(), input, outputCh))
	require.Len(t, outputCh, 1)

	output := <-outputCh
	require.NotNil(t, output.Frame)

	// Verify that output pixels differ from input: bilateral filter smoothed the noise.
	inputImg := makeCheckerboardYCbCr(320, 240)
	outputImg := frameToYCbCr(t, output.Frame.Frame)
	rmse := computeYPlaneRMSE(inputImg, outputImg)
	testifyassert.Greater(t, rmse, 0.1,
		"bilateral filter should measurably change a noisy frame (RMSE=%f)", rmse)

	// Verify the output isn't all zeros (filter produced actual content).
	hasNonZero := false
	for _, b := range outputImg.Y {
		if b != 0 {
			hasNonZero = true
			break
		}
	}
	testifyassert.True(t, hasNonZero, "output frame should contain non-zero pixel data")

	// Verify input frame itself was not mutated by the filter (filter works on a copy).
	currentInput := snapshotYPlane(t, input.Frame.Frame)
	testifyassert.Equal(t, inputSnapshot, currentInput,
		"input frame should not be mutated by the filter")
}

